import{_ as i,a0 as a,w as l,s as p,ao as u,I as o,x as n,a1 as s,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"Linux FAQ與答案：如何檢查我是否處於一個運行着的screen會話中 | LCTT x X-CMD","titleTemplate":false,"description":"Linux FAQ與答案：如何檢查我是否處於一個運行着的screen會話中 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux FAQ與答案：如何檢查我是否處於一個運行着的screen會話中 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux FAQ與答案：如何檢查我是否處於一個運行着的screen會話中 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140804 Linux FAQs with Answers--How to check if I am in a running screen session","title":"Linux FAQ與答案：如何檢查我是否處於一個運行着的screen會話中","tag":"201408","desc":""},"relativePath":"201408/20140804 Linux FAQs with Answers--How to check if I am in a running screen session.md","filePath":"[post].md"}'),c={name:"201408/20140804 Linux FAQs with Answers--How to check if I am in a running screen session.md"};function m(x,e,d,f,T,_){const t=a("Link");return l(),p("div",null,[e[11]||(e[11]=u(`<h1 id="linux-faq與答案-如何檢查我是否處於一個運行着的screen會話中" tabindex="-1">Linux FAQ與答案：如何檢查我是否處於一個運行着的screen會話中 <a class="header-anchor" href="#linux-faq與答案-如何檢查我是否處於一個運行着的screen會話中" aria-label="Permalink to “Linux FAQ與答案：如何檢查我是否處於一個運行着的screen會話中”">​</a></h1><blockquote><p><strong>問題</strong>：我經常使用screen命令來運行多個偽終端會話。好多次，我發現都記不得自己是否在一個screen會話中，還是在一個常規終端中。是否有一種簡便的方法來檢查我是否在一個運行着的screen會話中？</p></blockquote><p>一個快捷而又簡單的方法來檢查你是否處於一個screen偽終端中，還是在一個常規終端中，就是檢查STY環境變量。當調用了screen，就會把STY變量值設置為會話名。因此，如果STY環境變量被設置為任何非空字符串，就意味着你正處於一個screen會話中。</p><pre><code> $ echo $STY 
</code></pre><blockquote><p>2858.pts-3.my_host</p></blockquote><p>然而，請注意，上面的方法<strong>只有當</strong>你是在本地計算機上運行screen命令的時候。如果你從本地計算機的screen會話中SSH到任何遠程計算機上，遠程計算機上的STY變量不會被設置，儘管在技術上看，你仍然處於一個screen會話中。</p><p>事實上，一個更為可靠的檢查你是否處於一個screen會話中的方法，是按“Ctrl-a”+“Ctrl-t”。如果你處於screen會話中，終端會在底部顯示時間信息。</p><p><img src="https://farm6.staticflickr.com/5578/14821730712_6a139d72e9_z.jpg" alt=""></p><hr>`,9)),o("p",null,[e[1]||(e[1]=n("via: ",-1)),s(t,{href:"http://ask.xmodulo.com/check-running-screen-session.html"},{default:r(()=>[...e[0]||(e[0]=[n("http://ask.xmodulo.com/check-running-screen-session.html",-1)])]),_:1})]),o("p",null,[e[4]||(e[4]=n("譯者：",-1)),s(t,{href:"https://github.com/GOLinux"},{default:r(()=>[...e[2]||(e[2]=[n("GOLinux",-1)])]),_:1}),e[5]||(e[5]=n(" 校對：",-1)),s(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[3]||(e[3]=[n("wxy",-1)])]),_:1})]),o("p",null,[e[8]||(e[8]=n("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[6]||(e[6]=[n("LCTT",-1)])]),_:1}),e[9]||(e[9]=n(" 原創翻譯，",-1)),s(t,{href:"http://linux.cn/"},{default:r(()=>[...e[7]||(e[7]=[n("Linux中國",-1)])]),_:1}),e[10]||(e[10]=n(" 榮譽推出",-1))])])}const k=i(c,[["render",m]]);export{A as __pageData,k as default};
